59	+// configureAccessReporter is the small part of the authenticated API used by
60	+// onboarding. Keeping it narrow makes the state machine independently testable.
61	+type configureAccessReporter interface {
62	+	ReportEnable(ctx context.Context, remoteURL string) (*api.EnableRepoResponse, error)
