65	+// configureFlowDeps contains side effects used by the interactive configure
66	+// flow. Tests can replace individual operations without a keyring, browser,
67	+// GitHub CLI, or live control plane.
68	+type configureFlowDeps struct {
69	+	resolveAuth  func(context.Context) (statusTarget, error)
70	+	fetchProfile profileFetcher
71	+	runLogin     func(context.Context, io.Writer, io.Writer) error
72	+	accessClient func(context.Context) (configureAccessReporter, error)
73	+	coreClient   func() (*coreapi.Client, error)
74	+	openURL      browserOpenFunc
75	+	githubAdmin  func(context.Context, string, string) (bool, error)
76	+	now          func() time.Time
