79	+func newConfigureFlowDeps(insecure bool) configureFlowDeps {
80	+	return configureFlowDeps{
81	+		resolveAuth: func(ctx context.Context) (statusTarget, error) {
82	+			return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
83	+		},
84	+		fetchProfile: defaultFetchProfile,
85	+		runLogin: func(ctx context.Context, outW, errW io.Writer) error {
86	+			cmd := newLoginCmd()
87	+			cmd.SetContext(ctx)
88	+			cmd.SetOut(outW)
89	+			cmd.SetErr(errW)
90	+			return cmd.RunE(cmd, nil)
91	+		},
92	+		accessClient: func(ctx context.Context) (configureAccessReporter, error) {
93	+			return NewAuthenticatedAPIClient(ctx, insecure)
94	+		},
95	+		coreClient:  coreapi.New,
96	+		openURL:     openBrowser,
97	+		githubAdmin: configureGitHubAdmin,
