102	+// runConfigureOnboarding is a seam for command tests. Bare interactive
103	+// `entire configure` is the new end-to-end entry point; flag-based configure
104	+// remains the non-interactive settings editor.
105	+var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
106	+	return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
107	+}
108	+
109	+func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
110	+	cmd.SilenceUsage = true
111	+	ctx := cmd.Context()
112	+	outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
113	+
114	+	repoRoot, err := paths.WorktreeRoot(ctx)
115	+	if err != nil {
116	+		fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
117	+		return NewSilentError(errors.New("not a git repository"))
118	+	}
119	+	owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
120	+	if err != nil {
121	+		return err
122	+	}
123	+
124	+	profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
125	+	if err != nil {
126	+		return err
127	+	}
128	+
129	+	reporter, err := deps.accessClient(ctx)
130	+	if err != nil {
131	+		return fmt.Errorf("connect to Entire: %w", err)
132	+	}
133	+	access, err := reporter.ReportEnable(ctx, cleanRemote)
134	+	if err != nil {
135	+		return fmt.Errorf("check repository access: %w", err)
136	+	}
137	+	if !access.Connected {
138	+		if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, opts.Yes, deps); err != nil {
139	+			return err
140	+		}
141	+	}
142	+
143	+	client, err := deps.coreClient()
144	+	if err != nil {
145	+		return fmt.Errorf("connect to Entire control plane: %w", err)
146	+	}
147	+	placements, err := resolvePullablePlacements(ctx, client, owner, repo)
148	+	if err != nil {
149	+		return renderCoreError(err)
150	+	}
151	+	if len(placements) == 0 {
152	+		placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction, opts.Yes)
153	+		if err != nil {
154	+			return err
155	+		}
156	+	}
157	+	if len(placements) == 0 {
158	+		return errors.New("no usable mirror was selected")
159	+	}
160	+
161	+	manageRegionsHint := ""
162	+	if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
163	+		manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
164	+			configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
165	+	}
166	+	initialChanges, err := configureGitChanges(ctx, repoRoot)
167	+	if err != nil {
168	+		return err
169	+	}
170	+	branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
171	+	if branchErr != nil {
172	+		// Best-effort: local-only saves do not need a branch.
173	+		branch = ""
174	+	}
175	+	protected := false
176	+	protectionKnown := branch == ""
177	+	if branch != "" {
178	+		if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
179	+			protected = detected
180	+			protectionKnown = true
181	+		}
182	+	}
183	+	// Non-interactive onboarding has no confirmation step. If GitHub protection
184	+	// cannot be checked (common when gh is unavailable in CI), fail closed and
185	+	// use the review branch rather than pushing directly to the checked-out
186	+	// branch. Interactive users can still explicitly choose a direct push when
187	+	// protection is known not to block it.
188	+	protected = configureEffectiveProtection(protected, protectionKnown, opts.Yes)
189	+	branchPushSafe := false
190	+	if branch != "" && len(initialChanges) == 0 {
191	+		branchPushSafe = configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)
192	+	}
193	+	chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
194	+		ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
195	+		branch, protected, branchPushSafe, opts.Yes,
196	+	)
197	+	if err != nil {
198	+		return err
199	+	}
200	+	if saveChoice == configureSaveCancel {
201	+		fmt.Fprintln(outW, "Configuration cancelled.")
202	+		return nil
203	+	}
204	+	if saveChoice == "" {
205	+		fmt.Fprintln(outW, "No configuration changes.")
206	+		return nil
207	+	}
208	+
209	+	// Snapshot immediately before applying our changes. The form may have been
210	+	// open for an arbitrary amount of time, so the pre-form status is not a safe
211	+	// commit baseline: editor autosaves or another process may have changed files
212	+	// while the user was choosing options. Anything already dirty now is excluded
213	+	// from generated and disables automatic commit/push below.
214	+	beforeApply, err := configureGitChanges(ctx, repoRoot)
215	+	if err != nil {
216	+		return err
217	+	}
218	+	if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
219	+		(len(beforeApply) != 0 || !configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)) {
220	+		saveChoice = configureSaveLocal
221	+	}
222	+
223	+	forgeRemote, err := configureUseMirror(ctx, outW, errW, repoRoot, owner, repo, chosen)
224	+	if err != nil {
225	+		return err
226	+	}
227	+
228	+	if agentsChanged {
229	+		opts = configureOnboardingEnableOptions(opts)
230	+		if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
231	+			return err
232	+		}
233	+		// A local enabled:false override must not win over the newly written project
234	+		// configuration. setEnabledFlag updates the project and synchronizes an
235	+		// existing local override without replacing its other local-only fields.
236	+		if err := setEnabledFlag(ctx, true, true); err != nil {
237	+			return err
238	+		}
239	+	}
240	+
241	+	after, err := configureGitChanges(ctx, repoRoot)
242	+	if err != nil {
243	+		return err
244	+	}
245	+	generated := newConfigureChanges(beforeApply, after)
246	+	if agentsChanged {
247	+		fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
248	+	}
249	+
250	+	if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
251	+		if err := configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, deps.now); err != nil {
252	+			return err
253	+		}
254	+	} else if agentsChanged && len(generated) > 0 {
255	+		fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
256	+	}
257	+	fmt.Fprintln(outW, "✓ Configuration complete")
258	+	fmt.Fprintln(outW)
259	+	fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
260	+	fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
261	+	return nil
262	+}
