264	+func configureOnboardingEnableOptions(opts EnableOptions) EnableOptions {
265	+	opts.Yes = true
266	+	opts.UseProjectSettings = true
267	+	opts.UseLocalSettings = false
268	+	opts.SuppressDoneMessage = true
269	+	opts.SuppressAdditionalSetup = true
270	+	// Logged-in onboarding does not ask a separate telemetry question. The
271	+	// documented default is applied without prompting; existing settings and
272	+	// ENTIRE_TELEMETRY_OPTOUT remain authoritative.
273	+	return opts
274	+}
