280	+func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
281	+	raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
282	+	if err != nil {
283	+		return "", "", "", fmt.Errorf("read origin remote: %w", err)
284	+	}
285	+	info, err := gitremote.ParseURL(raw)
286	+	if err != nil {
287	+		return "", "", "", fmt.Errorf("parse origin remote: %w", err)
288	+	}
289	+	if info.Forge != mirrorUseForge {
290	+		return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
291	+	}
292	+	clean, err := cleanRemoteURLForReport(raw)
293	+	if err != nil {
294	+		return "", "", "", err
295	+	}
296	+	return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
297	+}
