299	+func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
300	+	target, err := deps.resolveAuth(ctx)
301	+	if err != nil {
302	+		return nil, err
303	+	}
304	+	if target.token != "" {
305	+		if err := api.RequireSecureURL(target.coreURL); err != nil {
306	+			return nil, fmt.Errorf("context login server URL check: %w", err)
307	+		}
308	+		if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
309	+			return profile, nil
310	+		} else if !isKeychainTokenRejected(profileErr) {
311	+			return nil, fmt.Errorf("validate login: %w", profileErr)
312	+		}
313	+	}
314	+
315	+	if err := deps.runLogin(ctx, outW, errW); err != nil {
316	+		return nil, fmt.Errorf("login: %w", err)
317	+	}
318	+	target, err = deps.resolveAuth(ctx)
319	+	if err != nil {
320	+		return nil, err
321	+	}
322	+	if target.token == "" {
323	+		return nil, errors.New("login completed without an active session")
324	+	}
325	+	if err := api.RequireSecureURL(target.coreURL); err != nil {
326	+		return nil, fmt.Errorf("context login server URL check: %w", err)
327	+	}
328	+	profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
329	+	if err != nil {
330	+		return nil, fmt.Errorf("validate login: %w", err)
331	+	}
332	+	fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
333	+	return profile, nil
334	+}
335	+
336	+func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, nonInteractive bool, deps configureFlowDeps) error {
337	+	fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
338	+	installURL := strings.TrimSpace(initial.InstallURL)
339	+	if installURL == "" {
340	+		installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
341	+	}
342	+
343	+	admin, adminErr := deps.githubAdmin(ctx, owner, repo)
344	+	if adminErr == nil && !admin {
345	+		fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
346	+		fmt.Fprintln(errW, "  Send them this link to continue:")
347	+		fmt.Fprintf(errW, "\n  %s\n", installURL)
348	+		return NewSilentError(errors.New("GitHub app installation required"))
349	+	}
350	+	if adminErr != nil {
351	+		switch {
352	+		case errors.Is(adminErr, errConfigureGHUnavailable):
353	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
354	+			fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
355	+		case errors.Is(adminErr, errConfigureGHUnauthenticated):
356	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
357	+			fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
358	+		default:
359	+			fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
360	+		}
361	+		fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
362	+		fmt.Fprintln(errW)
363	+	}
364	+
365	+	fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
366	+	fmt.Fprintf(outW, "  %s\n\n", installURL)
367	+	if nonInteractive {
368	+		return NewSilentError(errors.New("GitHub app installation required; install it with the URL above, then rerun 'entire configure --yes'"))
369	+	}
370	+	if err := deps.openURL(ctx, installURL); err != nil {
371	+		fmt.Fprintln(outW, "  Open the link above in your browser.")
372	+	}
373	+	stop := startSpinner(errW, "Waiting for installation")
374	+	stopped := false
375	+	defer func() {
376	+		if !stopped {
377	+			stop(false)
378	+		}
379	+	}()
380	+
381	+	waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
382	+	defer cancel()
383	+	ticker := time.NewTicker(configureAccessPollInterval)
384	+	defer ticker.Stop()
385	+	for {
386	+		select {
387	+		case <-waitCtx.Done():
388	+			return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
389	+		case <-ticker.C:
390	+			access, err := reporter.ReportEnable(waitCtx, cleanRemote)
391	+			if err == nil && access.Connected {
392	+				stop(true)
393	+				stopped = true
394	+				fmt.Fprintln(outW, "✓ Access granted")
395	+				return nil
396	+			}
397	+		}
398	+	}
399	+}
