401	+func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
402	+	runner := execRunner{}
403	+	if !ghAvailable(ctx, runner) {
404	+		return false, errConfigureGHUnavailable
405	+	}
406	+	if !ghAuthenticated(ctx, runner) {
407	+		return false, errConfigureGHUnauthenticated
408	+	}
409	+	out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
410	+	if err != nil {
411	+		return false, fmt.Errorf("check GitHub admin permission: %w", err)
412	+	}
413	+	admin, err := strconv.ParseBool(strings.TrimSpace(out))
414	+	if err != nil {
415	+		return false, fmt.Errorf("parse GitHub admin permission: %w", err)
416	+	}
417	+	return admin, nil
418	+}
