420	+func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string, nonInteractive bool) ([]coreapi.ResolvedPlacement, error) {
421	+	regions, err := availableRegions(ctx, client)
422	+	if err != nil {
423	+		return nil, fmt.Errorf("list regions: %w", err)
424	+	}
425	+	if len(regions) == 0 {
426	+		return nil, errors.New("no regions available to mirror into")
427	+	}
428	+	selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction, nonInteractive)
429	+	if err != nil {
430	+		return nil, err
431	+	}
432	+	results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
433	+	reportErr := reportMirrorResults(outW, errW, results)
434	+	placements := configureSuccessfulMirrorPlacements(selected, results)
435	+	if len(placements) > 0 {
436	+		if reportErr != nil {
437	+			fmt.Fprintf(errW, "Continuing with %d mirror(s) that succeeded.\n", len(placements))
438	+		}
439	+		return placements, nil
440	+	}
441	+	if reportErr != nil {
442	+		return nil, reportErr
443	+	}
444	+	return nil, errors.New("no usable mirrors were created")
445	+}
446	+
447	+func configureSuccessfulMirrorPlacements(selected []regionChoice, results []mirrorResult) []coreapi.ResolvedPlacement {
448	+	placements := make([]coreapi.ResolvedPlacement, 0, len(results))
449	+	for i, result := range results {
450	+		if i >= len(selected) || result.err != nil || result.cloneURL == "" {
451	+			continue
452	+		}
453	+		region := selected[i]
454	+		placements = append(placements, coreapi.ResolvedPlacement{
455	+			ClusterHost:  region.host,
456	+			Cell:         coreapi.NewOptString(region.slug),
457	+			Jurisdiction: coreapi.NewOptString(region.jurisdiction),
458	+		})
459	+	}
460	+	return placements
461	+}
