463	+func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string, nonInteractive bool) ([]regionChoice, error) {
464	+	opts, defaults := clusterChoices(regions, jurisdiction)
465	+	byHost := make(map[string]regionChoice, len(regions))
466	+	for _, region := range regions {
467	+		byHost[region.host] = region
468	+	}
469	+	selected := append([]string(nil), defaults...)
470	+	if nonInteractive {
471	+		if len(selected) == 0 && len(opts) > 0 {
472	+			selected = append(selected, opts[0].Value)
473	+		}
474	+		chosen := make([]regionChoice, 0, len(selected))
475	+		for _, host := range selected {
476	+			if region, ok := byHost[host]; ok {
477	+				chosen = append(chosen, region)
478	+			}
479	+		}
480	+		return chosen, nil
481	+	}
482	+	form := NewAccessibleForm(huh.NewGroup(
483	+		huh.NewMultiSelect[string]().
484	+			Title("Which regions should this repository live in?").
485	+			Description("Space to select, enter to confirm — your data stays in the selected regions.").
486	+			Options(opts...).
487	+			Height(multiSelectHeight(len(opts))).
488	+			Validate(func(values []string) error {
489	+				if len(values) == 0 {
490	+					return errors.New("select at least one region")
491	+				}
492	+				return nil
493	+			}).
494	+			Value(&selected),
495	+	))
496	+	if err := form.RunWithContext(ctx); err != nil {
497	+		if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
498	+			return nil, cancelErr
499	+		}
500	+		return nil, NewSilentError(errors.New("configure cancelled"))
501	+	}
502	+	chosen := make([]regionChoice, 0, len(selected))
503	+	for _, host := range selected {
504	+		if region, ok := byHost[host]; ok {
505	+			chosen = append(chosen, region)
506	+		}
507	+	}
508	+	return chosen, nil
509	+}
