679	+func sameStrings(a, b []string) bool {
680	+	if len(a) != len(b) {
681	+		return false
682	+	}
683	+	seen := make(map[string]int, len(a))
684	+	for _, value := range a {
685	+		seen[value]++
686	+	}
687	+	for _, value := range b {
688	+		seen[value]--
689	+		if seen[value] < 0 {
690	+			return false
691	+		}
692	+	}
693	+	return true
694	+}
