960	+func runConfigureAgentManagement(cmd *cobra.Command, opts EnableOptions) error {
961	+	cmd.SilenceUsage = true
962	+	ctx := cmd.Context()
963	+	outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
964	+	repoRoot, err := paths.WorktreeRoot(ctx)
965	+	if err != nil {
966	+		return errors.New("not a git repository")
967	+	}
968	+	if !interactive.CanPromptInteractively() {
969	+		return runManageAgents(ctx, outW, opts, nil)
970	+	}
971	+
972	+	initialChanges, err := configureGitChanges(ctx, repoRoot)
973	+	if err != nil {
974	+		return err
975	+	}
976	+	branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
977	+	if branchErr != nil {
978	+		branch = ""
979	+	}
980	+	owner, repo, _, identityErr := configureRepoIdentity(ctx)
981	+	forgeRemote := ""
982	+	if identityErr == nil {
983	+		remotes, remotesErr := listGitRemotes(ctx, repoRoot)
984	+		if remotesErr != nil {
985	+			return remotesErr
986	+		}
987	+		forgeRemote, err = configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, "")
988	+		if err != nil {
989	+			return err
990	+		}
991	+	}
992	+	protected := false
993	+	if branch != "" && identityErr == nil {
994	+		if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
995	+			protected = detected
996	+		}
997	+	}
998	+	pushSafe := branch != "" && forgeRemote != "" && len(initialChanges) == 0 &&
999	+		configureBranchMatchesRemoteHead(ctx, repoRoot, forgeRemote, "refs/heads/"+branch)
1000	+	installedNames := GetAgentsWithHooksInstalled(ctx)
1001	+	selectedNames, saveChoice, changed, err := promptConfigureAgentsAndSave(ctx, errW, installedNames, branch, protected, pushSafe)
1002	+	if err != nil {
1003	+		return err
1004	+	}
1005	+	if saveChoice == configureSaveCancel {
1006	+		fmt.Fprintln(outW, "Agent configuration cancelled.")
1007	+		return nil
1008	+	}
1009	+	if !changed {
1010	+		fmt.Fprintln(outW, "No agent configuration changes.")
1011	+		return nil
1012	+	}
1013	+
1014	+	beforeApply, err := configureGitChanges(ctx, repoRoot)
1015	+	if err != nil {
1016	+		return err
1017	+	}
1018	+	if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
1019	+		(len(beforeApply) != 0 || !configureBranchMatchesRemoteHead(ctx, repoRoot, forgeRemote, "refs/heads/"+branch)) {
1020	+		saveChoice = configureSaveLocal
1021	+	}
1022	+	if err := applyAgentChanges(ctx, outW, selectedNames, installedNames, opts); err != nil {
1023	+		return err
1024	+	}
1025	+	if saveChoice != configureSaveDirect && saveChoice != configureSaveNewBranch {
1026	+		return nil
1027	+	}
1028	+	afterApply, err := configureGitChanges(ctx, repoRoot)
1029	+	if err != nil {
