1076	+
1077	+func configureNonInteractiveSaveChoice(hasChanges, requiresPush, protected bool) string {
1078	+	if !hasChanges {
1079	+		return ""
1080	+	}
1081	+	return defaultConfigureSaveChoice(true, requiresPush, protected)
1082	+}
1083	+
1084	+func configureEffectiveProtection(protected, known, nonInteractive bool) bool {
1085	+	return protected || (nonInteractive && !known)
1086	+}
1087	+
1088	+func defaultConfigureSaveChoice(hasChanges, requiresPush, protected bool) string {
1089	+	if !hasChanges {
1090	+		return configureSaveCancel
1091	+	}
1092	+	if !requiresPush {
1093	+		return configureSaveLocal
1094	+	}
1095	+	if protected {
1096	+		return configureSaveNewBranch
1097	+	}
1098	+	return configureSaveDirect
1099	+}
1100	+
1101	+func configureSaveOptions(branch string, protected, requiresPush, hasChanges bool, _ string) []huh.Option[string] {
1102	+	cancel := huh.NewOption("Cancel", configureSaveCancel)
1103	+	if !hasChanges {
1104	+		return []huh.Option[string]{cancel}
1105	+	}
1106	+	if !requiresPush {
1107	+		return []huh.Option[string]{
1108	+			huh.NewOption("Save", configureSaveLocal),
1109	+			cancel,
1110	+		}
1111	+	}
1112	+
1113	+	newBranch := huh.NewOption("Save — push to a new branch, review before it lands", configureSaveNewBranch)
1114	+	if protected {
1115	+		// huh has no disabled-option primitive. Keep the protected destination
1116	+		// visible in the description, but omit it from keyboard navigation.
1117	+		return []huh.Option[string]{newBranch, cancel}
1118	+	}
1119	+	return []huh.Option[string]{
1120	+		huh.NewOption("Save — push to "+branch, configureSaveDirect),
1121	+		newBranch,
1122	+		cancel,
1123	+	}
1124	+}
1125	+
1126	+func configureSaveDescription(branch string, protected, requiresPush, hasChanges bool) string {
1127	+	if !hasChanges {
1128	+		return lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Render("  Save — no changes")
1129	+	}
1130	+	if !requiresPush || !protected {
1131	+		return ""
1132	+	}
1133	+	return lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Render("  Save — push to " + branch + " — protected branch")
1134	+}
1135	+
1136	+func configureOptionsContain(options []huh.Option[string], value string) bool {
1137	+	for _, option := range options {
1138	+		if option.Value == value {
1139	+			return true
1140	+		}
1141	+	}
1142	+	return false
1143	+}
1144	+
1145	+func configureRadioLabel(label string, selected bool) string {
1146	+	marker := lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Render("○")
1147	+	if selected {
1148	+		marker = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Success)).Render("●")
1149	+	}
1150	+	return marker + " " + label
1151	+}
1152	+
1153	+func newConfigureForm(groups ...*huh.Group) *huh.Form {
1154	+	// Do not start with NewAccessibleForm here: huh fields retain the first
1155	+	// theme assigned to them, so applying configureFormTheme afterward would
1156	+	// leave the standard rail and `>` cursor in place. Install this theme first.
1157	+	form := huh.NewForm(groups...).WithTheme(configureFormTheme())
1158	+	if IsAccessibleMode() {
1159	+		form = form.WithAccessible(true)
1160	+	}
1161	+	return form
1162	+}
1163	+
1164	+func configureFormTheme() huh.Theme {
1165	+	return huh.ThemeFunc(func(isDark bool) *huh.Styles {
1166	+		theme := uiform.Theme().Theme(isDark)
1167	+		success := lipgloss.Color(palette.Success)
1168	+		muted := lipgloss.Color(palette.Muted)
1169	+
1170	+		// Radio and checkbox lists use the same active-row indicator. Selection
1171	+		// remains green and independent from the orange `>` cursor.
1172	+		theme.FieldSeparator = lipgloss.NewStyle().SetString("")
1173	+		theme.Focused.Base = lipgloss.NewStyle()
1174	+		theme.Blurred.Base = lipgloss.NewStyle()
1175	+		theme.Focused.SelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1176	+		theme.Blurred.SelectSelector = lipgloss.NewStyle().SetString("  ")
1177	+		theme.Focused.MultiSelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1178	+		theme.Blurred.MultiSelectSelector = lipgloss.NewStyle().SetString("  ")
1179	+		theme.Focused.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
1180	+		theme.Blurred.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
1181	+		theme.Focused.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
1182	+		theme.Blurred.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
1183	+		theme.Focused.SelectedOption = theme.Focused.SelectedOption.UnsetForeground()
1184	+		theme.Blurred.SelectedOption = theme.Blurred.SelectedOption.UnsetForeground()
1185	+		// Enabled options keep normal text contrast whether selected or not.
1186	+		// Muting the empty checkbox is sufficient; muting the label itself can
1187	+		// incorrectly communicate that the option is disabled.
1188	+		theme.Focused.UnselectedOption = theme.Focused.UnselectedOption.UnsetForeground()
1189	+		theme.Blurred.UnselectedOption = theme.Blurred.UnselectedOption.UnsetForeground()
1190	+		return theme
1191	+	})
1192	+}
1193	+
1194	+func configureQuestionTitle(question string, focused bool) string {
1195	+	color := palette.Muted
1196	+	if focused {
1197	+		color = palette.Warning
1198	+	}
1199	+	marker := lipgloss.NewStyle().Foreground(lipgloss.Color(color)).Render("?")
1200	+	heading := lipgloss.NewStyle().Bold(true).Render(question)
1201	+	return marker + " " + heading
1202	+}
1203	+
1204	+func configureAgentOptions(options []huh.Option[string], selected map[types.AgentName]struct{}) []huh.Option[string] {
1205	+	plain := make([]huh.Option[string], 0, len(options))
1206	+	for _, option := range options {
1207	+		item := huh.NewOption(option.Key, option.Value)
1208	+		if _, ok := selected[types.AgentName(option.Value)]; ok {
1209	+			item = item.Selected(true)
1210	+		}
1211	+		plain = append(plain, item)
1212	+	}
1213	+	return plain
1214	+}
1215	+
1216	+func configureCurrentUpstream(ctx context.Context, repoRoot string) string {
1217	+	raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1218	+	if err != nil {
1219	+		return ""
1220	+	}
1221	+	info, err := gitremote.ParseURL(raw)
1222	+	if err != nil || info.Protocol != gitremote.ProtocolEntire {
1223	+		return ""
1224	+	}
1225	+	return info.Host
1226	+}
1227	+
1228	+func configurePlacementOrder(placements []coreapi.ResolvedPlacement, currentHost, jurisdiction string) []coreapi.ResolvedPlacement {
1229	+	ordered := append([]coreapi.ResolvedPlacement(nil), placements...)
1230	+	sort.SliceStable(ordered, func(i, j int) bool {
1231	+		iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
1232	+		jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
1233	+		if iCurrent != jCurrent {
1234	+			return iCurrent
1235	+		}
1236	+		iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
1237	+		jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
1238	+		if currentHost == "" && iHome != jHome {
1239	+			return iHome
1240	+		}
1241	+		return configurePlacementLabel(ordered[i]) < configurePlacementLabel(ordered[j])
1242	+	})
1243	+	return ordered
1244	+}
1245	+
1246	+func configurePlacementLabel(placement coreapi.ResolvedPlacement) string {
1247	+	if jurisdiction := strings.ToLower(strings.TrimSpace(placement.Jurisdiction.Or(""))); jurisdiction != "" {
1248	+		if name, ok := configureJurisdictionNames[jurisdiction]; ok {
1249	+			return name
1250	+		}
1251	+		return strings.ToUpper(jurisdiction)
1252	+	}
