+
+func (field *configureSaveField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
+	model, cmd := field.Select.Update(msg)
+	if updated, ok := model.(*huh.Select[string]); ok {
+		field.Select = updated
+	}
+	return field, cmd
