+func availableConfigureRemoteName(remotes map[string]bool, candidates ...string) string {
+	for _, candidate := range candidates {
+		if !remotes[candidate] {
+			return candidate
+		}
+	}
+	for i := 2; ; i++ {
+		candidate := fmt.Sprintf("github-%d", i)
+		if !remotes[candidate] {
+			return candidate
+		}
+	}
+}
