+	}
+	if !configureGitHubAPINotFound(classicErr) {
+		return false, fmt.Errorf("check classic GitHub branch protection: %w", classicErr)
+	}
+	if rulesErr != nil {
+		return false, fmt.Errorf("check GitHub branch rules: %w", rulesErr)
+	}
+	return false, nil
+}
