+		return false, fmt.Errorf("check GitHub branch rules: %w", rulesErr)
+	}
+	return false, nil
+}
+
+func configureGitHubAPINotFound(err error) bool {
+	return err != nil && strings.Contains(err.Error(), "HTTP 404")
